      const n = choose(rng, [2, 3, 4]), f = choose(rng, [4, 8, 16]); const ratio = f ** (1 / n); const k = pick(rng, 0.5, 2, 0.5); const P1 = choose(rng, [0.1, 0.2, 0.5]);
      const y1 = +(k * P1 ** (1 / n)).toFixed(4), y2 = +(k * (P1 * f) ** (1 / n)).toFixed(4); const nn = Math.log(f) / Math.log(y2 / y1);
      return { q: `For a Freundlich isotherm, x/m is ${y1} g/g at P = ${P1} atm and ${y2} g/g at P = ${+(P1 * f).toFixed(3)} atm. Find n (nearest whole number).`, answer: n, tol: 0.15, f, y1, y2, n,
        sol: `<p>(x/m)<sub>2</sub>/(x/m)<sub>1</sub> = (P<sub>2</sub>/P<sub>1</sub>)<sup>1/n</sup>: ${(y2 / y1).toFixed(3)} = ${f}<sup>1/n</sup>.</p><p>1/n = log(${(y2 / y1).toFixed(3)})/log ${f}, so n = <b>${n}</b>.</p>` };
