      const K = choose(rng, [0.2, 0.5, 1, 2]), th = choose(rng, [0.5, 0.6, 0.75, 0.8, 0.9]); const P = th / (1 - th) / K;
      return { q: `The Langmuir constant of a gas on a solid is K = ${K} atm<sup>-1</sup>. At what pressure in atm is the fraction of surface covered &theta; = ${th}?`, answer: +P.toFixed(3), tol: Math.max(0.02, P * 0.01), unit: `atm`, K, th,
        sol: `<p>&theta; = KP/(1 + KP), so KP = &theta;/(1 - &theta;) = ${th}/${+(1 - th).toFixed(2)} = ${(th / (1 - th)).toFixed(3)}.</p><p>P = ${(th / (1 - th)).toFixed(3)}/${K} = <b>${P.toFixed(3)} atm</b>.</p>` };
