const XM = (level, sub, gid, title, l1, l2, map, whys, trap) => {
  const LL = 'pqrstu';
  groups[gid] = { title, list1: l1.map((t, i) => `${'ABCD'[i]}. ${t}`), list2: l2.map((t, i) => `${LL[i]}. ${t}`) };
  const code = (m) => m.map((v, i) => `${'ABCD'[i]}-${LL[v]}`).join(', ');
  const sw = (a, i, k) => { const b = [...a]; [b[i], b[k]] = [b[k], b[i]]; return b; };
  mat(level, sub, gid, `Choose the correct matching of List I with List II.`, code(map), [sw(map, 0, 1), sw(map, 2, 3), sw(map, 0, 3)].map(code), whys.map((w, i) => `<p>${'ABCD'[i]} &rarr; ${LL[map[i]]}: ${w}</p>`).join(''), trap);
};
const cntS = (level, sub, q, options, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'statements', exams: EXM[level], sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
Object.assign(groups, {
  xp5: { title: `A mixed oxide`, passage: `<p>In a mixed oxide, the oxide ions form a cubic close-packed (fcc) arrangement. Cations A occupy one-eighth of the tetrahedral voids and cations B occupy one-half of the octahedral voids.</p>` },
  xp6: { title: `Adsorption data for a gas on charcoal`, passage: `<p>At a fixed temperature a gas follows the Freundlich isotherm x/m = kP<sup>1/n</sup>. At 1 atm the amount adsorbed is x/m = 0.2 g per g of charcoal, and at 8 atm it is 0.8 g per g.</p>` },
});
// ----- level 2 -----
mk(2, `voids`, `The number of tetrahedral voids per atom in a cubic close-packed structure is`, `2`, [`1`, `4`, `8`], `<p>Per atom of the lattice there are two tetrahedral voids and one octahedral void. A fcc cell has 4 atoms, 8 tetrahedral and 4 octahedral voids.</p>`);
mk(2, `crystal structures`, `The coordination number of Na<sup>+</sup> in rock salt (NaCl) is`, `6`, [`4`, `8`, `12`], `<p>In NaCl each Na<sup>+</sup> sits in an octahedral void formed by six Cl<sup>&minus;</sup> ions, so the coordination number is 6 (and also 6 for Cl<sup>&minus;</sup>).</p>`);
mk(2, `crystal structures`, `In zinc blende (ZnS), the coordination number of Zn<sup>2+</sup> is`, `4`, [`6`, `8`, `2`], `<p>S<sup>2&minus;</sup> ions form a fcc lattice, and Zn<sup>2+</sup> occupies half of the tetrahedral voids. Each Zn<sup>2+</sup> has 4 S<sup>2&minus;</sup> neighbours, and each S<sup>2&minus;</sup> has 4 Zn<sup>2+</sup>.</p>`);
mk(2, `colloids`, `Brownian motion in a colloidal sol is caused by`, `unequal bombardment of the particles by the molecules of the dispersion medium`, [`convection currents in the sol`, `repulsion between the charged particles`, `gravity acting on the particles`], `<p>The particles are small enough to be knocked about by the random collisions of the medium&rsquo;s molecules. The resulting zig-zag motion helps to keep the sol stable against settling.</p>`);
mk(2, `colloids`, `The hydrated ferric oxide sol, Fe(OH)<sub>3</sub>, carries`, `a positive charge`, [`a negative charge`, `no charge`, `a charge that changes sign with time`], `<p>Metal hydroxides and hydrated oxides such as Fe(OH)<sub>3</sub> and Al(OH)<sub>3</sub> form positive sols by adsorbing their own cations (Fe<sup>3+</sup>). As<sub>2</sub>S<sub>3</sub> and gold sols are negative.</p>`);
nat(2, `voids`, `How many octahedral voids are there for every 4 atoms of a close-packed lattice?`, 4, 0, ``, `<p>There is one octahedral void per atom, so 4 atoms have <b>4</b> octahedral voids.</p>`, ``, () => 4);
// ----- level 3 -----
nat(3, `voids`, `How many tetrahedral voids are there inside one fcc unit cell?`, 8, 0, ``, `<p>One fcc unit cell has 4 atoms, and 2 tetrahedral voids per atom gives 4 &times; 2 = <b>8</b> (one in each of the eight small cubes).</p>`, ``, () => 4 * 2);
nat(3, `packing`, `What percentage of the volume of a body-centred cubic lattice is empty space (to the nearest whole number)?`, 32, 0, `%`, `<p>bcc packing efficiency is 68 %, so the empty space is 100 &minus; 68 = <b>32 %</b>.</p>`, `Do not answer with the packing efficiency itself.`, () => 100 - 68);
mk(3, `radius ratio`, `A cation to anion radius ratio of 0.52 suggests that the cation is surrounded by`, `six anions (octahedral)`, [`four anions (tetrahedral)`, `eight anions (cubic)`, `three anions (triangular)`], `<p>0.414 to 0.732 corresponds to an octahedral hole and coordination number 6. 0.225 to 0.414 is tetrahedral (4), 0.732 to 1 is cubic (8).</p>`);
mk(3, `crystal structures`, `In fluorite (CaF<sub>2</sub>), the coordination numbers of Ca<sup>2+</sup> and F<sup>&minus;</sup> are`, `8 and 4`, [`4 and 8`, `6 and 6`, `8 and 8`], `<p>Ca<sup>2+</sup> forms a fcc lattice and F<sup>&minus;</sup> fills all the tetrahedral voids. Each F<sup>&minus;</sup> has 4 Ca<sup>2+</sup> neighbours, and each Ca<sup>2+</sup> has 8 F<sup>&minus;</sup> neighbours (hence 8 : 4).</p>`, `In antifluorite (Na<sub>2</sub>O) it is the other way round, 4 : 8.`);
mk(3, `electrical properties`, `Germanium doped with gallium becomes`, `a p-type semiconductor, with positive holes as the main charge carriers`, [`an n-type semiconductor`, `an insulator`, `a superconductor`], `<p>Ga has three valence electrons, one fewer than Ge, so each Ga atom leaves a hole (electron deficiency). The conduction is by holes: p-type. Doping with a group 15 element such as As gives n-type.</p>`);
mk(3, `catalysis`, `A catalyst that is more specific because only molecules of a certain size can enter its pores, as in ZSM-5, is called`, `a shape-selective catalyst`, [`a promoter`, `a poison`, `an autocatalyst`], `<p>Zeolites have channels of fixed size, so only reactants and products that fit can pass. ZSM-5 converts alcohols to a petrol mixture of hydrocarbons.</p>`);
mk(3, `catalysis`, `Molybdenum is added in the Haber process to increase the activity of iron. Molybdenum is therefore a`, `promoter`, [`catalytic poison`, `autocatalyst`, `inhibitor`], `<p>A promoter enhances the activity of a catalyst without being a catalyst itself. A poison (like CO or As) reduces activity.</p>`);
mk(3, `adsorption`, `A plot of log(x/m) against log P for a gas adsorbed according to the Freundlich isotherm is a straight line whose slope is`, `1/n`, [`n`, `log k`, `k`], `<p>Taking logarithms: log(x/m) = log k + (1/n) log P. The slope is 1/n and the intercept is log k.</p>`);
mk(3, `adsorption`, `On increasing the temperature, physical adsorption generally`, `decreases, because it is exothermic and the weak forces are overcome`, [`increases, because it needs activation energy`, `first increases then decreases`, `does not change`], `<p>Adsorption is exothermic, so by Le Chatelier&rsquo;s principle a higher temperature reduces it. Chemisorption first rises (it needs activation energy) and then falls.</p>`, `The rise-then-fall pattern belongs to chemisorption, not physisorption.`);
mk(3, `colloids`, `The gold number of a protective colloid is a measure of`, `how effectively it protects a gold sol; a smaller number means better protection`, [`how effectively it protects a gold sol; a larger number means better protection`, `the mass of gold in the sol`, `the charge on the gold particles`], `<p>The gold number is the minimum mass in milligrams of the protective colloid needed to prevent the coagulation of 10 mL of a red gold sol on the addition of 1 mL of 10 % NaCl. A small mass is enough for an effective protective colloid, so a smaller gold number means better protection (gelatin 0.005&ndash;0.01, starch about 25).</p>`);
mk(3, `types of solids`, `Which of the following is a molecular solid?`, `solid carbon dioxide (dry ice)`, [`silicon carbide`, `diamond`, `sodium chloride`], `<p>In dry ice, separate CO<sub>2</sub> molecules are held by weak van der Waals forces. SiC and diamond are covalent network solids, and NaCl is ionic.</p>`);
nat(3, `unit cells`, `Find the edge length of the body-centred cubic unit cell of iron, whose atomic radius is 124 pm, in pm.`, 286.4, 0.5, `pm`, `<p>In bcc the atoms touch along the body diagonal: &radic;3 a = 4r. So a = 4 &times; 124/1.732 = <b>286.4 pm</b>.</p>`, `The atoms touch along the body diagonal in bcc, but along the face diagonal in fcc.`, () => 4 * 124 / Math.sqrt(3));
nat(3, `magnetic properties`, `Find the spin-only magnetic moment of Mn<sup>2+</sup> in Bohr magnetons (Mn<sup>2+</sup> is high spin d<sup>5</sup>).`, 5.92, 0.02, `BM`, `<p>d<sup>5</sup> has 5 unpaired electrons. &mu; = &radic;(n(n + 2)) = &radic;(5 &times; 7) = &radic;35 = <b>5.92 BM</b>.</p>`, ``, () => Math.sqrt(35));
nat(3, `colloids`, `The flocculation values of a negative As<sub>2</sub>S<sub>3</sub> sol are 50 mmol/L for NaCl and 0.5 mmol/L for AlCl<sub>3</sub>. How many times more effective at coagulation is AlCl<sub>3</sub> than NaCl?`, 100, 0, ``, `<p>Coagulating power is inversely proportional to the flocculation value: 50/0.5 = <b>100</b>.</p>`, `A smaller flocculation value means stronger coagulating power.`, () => 50 / 0.5);
// ----- level 4 -----
mk(4, `crystal structures`, `In a cubic unit cell, atoms A occupy the corners and atoms B occupy the centres of the 12 edges. The formula of the compound is`, `AB<sub>3</sub>`, [`A<sub>2</sub>B<sub>3</sub>`, `AB<sub>12</sub>`, `A<sub>8</sub>B<sub>12</sub>`], `<p>A: 8 &times; 1/8 = 1. B: 12 &times; 1/4 = 3. Formula AB<sub>3</sub>. (Add a third atom X at the body centre to get the perovskite ABX<sub>3</sub> arrangement.)</p>`);
mk(4, `formula of a crystal`, `In a rock-salt type unit cell of AX (X at the corners and face centres, A at the edge centres and body centre), all X ions on the face centres are removed. The new formula is`, `A<sub>4</sub>X`, [`AX`, `A<sub>4</sub>X<sub>3</sub>`, `A<sub>2</sub>X`], `<p>X left: 8 corners &times; 1/8 = 1. A: 12 edges &times; 1/4 + 1 (body centre) = 4. The formula becomes A<sub>4</sub>X.</p>`, `Count the shares of each position, not the number of sites.`);
mk(4, `formula of a crystal`, `In a cubic unit cell, atoms A are at the corners except that one corner is vacant, and atoms B are at the centres of all six faces. The formula is`, `A<sub>7</sub>B<sub>24</sub>`, [`A<sub>7</sub>B<sub>6</sub>`, `A<sub>8</sub>B<sub>6</sub>`, `A<sub>7</sub>B<sub>3</sub>`], `<p>A: 7 corners &times; 1/8 = 7/8. B: 6 &times; 1/2 = 3. A : B = 7/8 : 3 = 7 : 24. Formula A<sub>7</sub>B<sub>24</sub>.</p>`);
mk(4, `crystal structures`, `The mineral perovskite, CaTiO<sub>3</sub>, has Ca<sup>2+</sup> at the corners of a cube, Ti<sup>4+</sup> at the body centre and O<sup>2&minus;</sup> at the face centres. The coordination number of Ti<sup>4+</sup> is`, `6`, [`12`, `8`, `4`], `<p>The six face-centre O<sup>2&minus;</sup> ions lie at a distance a/2 from the body centre, giving an octahedron: coordination number 6. (Ca<sup>2+</sup> has 12.) Check the formula: Ca 8 &times; 1/8 = 1, Ti 1, O 6 &times; 1/2 = 3, so CaTiO<sub>3</sub>.</p>`);
mk(4, `voids`, `In the spinel MgAl<sub>2</sub>O<sub>4</sub> the oxide ions form a cubic close-packed lattice, Mg<sup>2+</sup> occupies tetrahedral voids and Al<sup>3+</sup> occupies octahedral voids. The fractions of tetrahedral and octahedral voids occupied are respectively`, `1/8 and 1/2`, [`1/2 and 1/8`, `1/4 and 1/4`, `1/8 and 1/4`], `<p>For 4 O<sup>2&minus;</sup> (one MgAl<sub>2</sub>O<sub>4</sub> unit) there are 8 tetrahedral and 4 octahedral voids. Mg: 1 of 8 = 1/8. Al: 2 of 4 = 1/2.</p>`, `Divide by the total number of voids of each type, not by the number of oxide ions.`);
mk(4, `defects`, `Which of the following changes the density of a crystal?`, `Schottky defect, which lowers the density`, [`Frenkel defect, which lowers the density`, `Frenkel defect, which raises the density`, `Schottky defect, which raises the density`], `<p>A Schottky defect removes ions from the crystal, so the mass falls while the volume stays about the same: density decreases. A Frenkel defect only moves an ion to an interstitial position, so mass and volume are unchanged and so is the density.</p>`);
mk(4, `defects`, `NaCl heated in sodium vapour turns yellow. The colour is due to`, `F-centres, electrons trapped at anion vacancies`, [`Frenkel defects`, `Schottky defects`, `interstitial chloride ions`], `<p>Sodium atoms deposit on the surface and the Cl<sup>&minus;</sup> ions formed diffuse in, leaving anion vacancies. The ionised electron of Na is trapped in the vacancy (F-centre) and absorbs visible light, giving a yellow colour. It is a metal excess defect.</p>`);
mk(4, `defects`, `Doping NaCl with a small amount of SrCl<sub>2</sub> creates`, `cation vacancies, one for every Sr<sup>2+</sup> that replaces two Na<sup>+</sup>`, [`anion vacancies`, `interstitial Sr<sup>2+</sup> ions only`, `F-centres`], `<p>Sr<sup>2+</sup> takes the place of one Na<sup>+</sup>, but it has two positive charges, so another Na<sup>+</sup> site must be empty to keep the crystal neutral. Each Sr<sup>2+</sup> therefore produces one cation vacancy.</p>`);
mk(4, `magnetic properties`, `Fe<sub>3</sub>O<sub>4</sub> (magnetite) is ferrimagnetic. On heating above its Curie temperature it becomes`, `paramagnetic`, [`diamagnetic`, `antiferromagnetic`, `a superconductor`], `<p>Heat randomises the alignment of the magnetic dipoles, so the permanent ordered magnetism is lost, and the substance behaves as a paramagnet.</p>`);
mk(4, `adsorption`, `A gas adsorbs spontaneously on a solid surface and the entropy of the gas decreases. Therefore the adsorption must be`, `exothermic`, [`endothermic`, `thermoneutral`, `impossible at any temperature`], `<p>&Delta;G = &Delta;H &minus; T&Delta;S must be negative. Since the gas loses freedom, &Delta;S is negative, so &minus;T&Delta;S is positive. Only a negative &Delta;H can make &Delta;G negative.</p>`);
mk(4, `emulsions`, `Which of the following is an oil-in-water (O/W) emulsion?`, `milk`, [`butter`, `cold cream`, `cod-liver oil in oil`], `<p>In milk, fat droplets are dispersed in water (the emulsifier is casein). Butter and cold cream are water-in-oil emulsions. A dilution test (adding water) mixes with O/W emulsions only.</p>`);
mk(4, `colloids`, `Coagulation of a positively charged Fe(OH)<sub>3</sub> sol is most effective with`, `K<sub>3</sub>[Fe(CN)<sub>6</sub>]`, [`NaCl`, `BaCl<sub>2</sub>`, `Na<sub>2</sub>SO<sub>4</sub>`], `<p>For a positive sol the coagulating ion is the anion, and (Hardy&ndash;Schulze rule) the higher the charge the more effective: [Fe(CN)<sub>6</sub>]<sup>3&minus;</sup> (3) &gt; SO<sub>4</sub><sup>2&minus;</sup> (2) &gt; Cl<sup>&minus;</sup> (1). Barium chloride has Cl<sup>&minus;</sup> as the effective ion.</p>`, `Use the charge opposite to that of the sol.`);
mk(4, `colloids`, `When a sol of As<sub>2</sub>S<sub>3</sub> is mixed with a sol of Fe(OH)<sub>3</sub>,`, `mutual coagulation occurs, because the charges are opposite`, [`nothing happens, both are stable`, `a more stable sol forms`, `the As<sub>2</sub>S<sub>3</sub> sol turns positive`], `<p>The negative As<sub>2</sub>S<sub>3</sub> particles and the positive Fe(OH)<sub>3</sub> particles neutralise each other&rsquo;s charge, so both sols precipitate.</p>`);
mk(4, `micelles`, `Micelles form from soap molecules only above`, `the critical micelle concentration and above the Krafft temperature`, [`the critical micelle concentration at any temperature`, `the Krafft temperature at any concentration`, `the boiling point of water`], `<p>Micellisation needs both: a concentration above the CMC and a temperature above the Krafft temperature, where the solubility of the surfactant becomes large enough to reach the CMC.</p>`);
msq(4, `crystal structures`, `Which of the following pairs of coordination numbers (cation : anion) are correct?`, [`NaCl, 6 : 6`, `CsCl, 8 : 8`, `ZnS (zinc blende), 6 : 6`, `CaF<sub>2</sub> (Ca : F), 8 : 4`], [0, 1, 3], `<p>Zinc blende has 4 : 4, so C is wrong. The others are correct.</p>`);
msq(4, `voids`, `For a cubic close-packed lattice of N atoms, which statements are correct?`, [`There are N octahedral voids.`, `There are 2N tetrahedral voids.`, `The radius of an octahedral void is 0.414 times that of the atom.`, `The radius of a tetrahedral void is larger than that of an octahedral void.`], [0, 1, 2], `<p>D is false: tetrahedral voids (0.225 r) are smaller than octahedral voids (0.414 r).</p>`);
msq(4, `defects`, `Which statements about point defects are correct?`, [`A Schottky defect decreases the density.`, `A Frenkel defect does not change the density.`, `A Schottky defect keeps the crystal electrically neutral.`, `Frenkel defects are common in NaCl.`], [0, 1, 2], `<p>NaCl has similar ion sizes and a high coordination number, so it shows Schottky defects. Frenkel defects occur when the cation is much smaller than the anion (AgBr, ZnS), so D is false.</p>`);
msq(4, `electrical properties`, `Which statements about conductors and semiconductors are correct?`, [`In a metal the valence band overlaps with the conduction band or is only partly filled.`, `The band gap of an insulator is large.`, `The conductivity of a semiconductor increases on heating.`, `The conductivity of a metal increases on heating.`], [0, 1, 2], `<p>In metals, heating increases the vibrations of the kernels and so scatters the electrons: conductivity falls, so D is false.</p>`);
msq(4, `magnetic properties`, `Which of the following are paramagnetic?`, [`Ti<sup>3+</sup>`, `Zn<sup>2+</sup>`, `Cu<sup>2+</sup>`, `Sc<sup>3+</sup>`], [0, 2], `<p>Ti<sup>3+</sup> is d<sup>1</sup> and Cu<sup>2+</sup> is d<sup>9</sup> (one unpaired electron each). Zn<sup>2+</sup> is d<sup>10</sup> and Sc<sup>3+</sup> is d<sup>0</sup>, so both are diamagnetic.</p>`);
msq(4, `adsorption`, `Which statements about chemisorption are correct?`, [`It involves the formation of chemical bonds.`, `It is highly specific.`, `It usually forms a monolayer.`, `It is reversible and decreases with increasing pressure.`], [0, 1, 2], `<p>Chemisorption is largely irreversible and increases with pressure (up to monolayer coverage), so D is wrong.</p>`);
msq(4, `colloids`, `Which of the following give the Tyndall effect?`, [`a gold sol`, `a true solution of NaCl`, `smoke in air`, `milk`], [0, 2, 3], `<p>Colloids scatter light and show the Tyndall beam. A true solution has particles too small to scatter noticeably.</p>`);
msq(4, `catalysis`, `Which of the following are examples of homogeneous catalysis?`, [`NO in the lead chamber process for SO<sub>2</sub> oxidation`, `Pt in the oxidation of SO<sub>2</sub>`, `H<sup>+</sup> in the hydrolysis of an ester in water`, `Fe in the Haber process`], [0, 2], `<p>Homogeneous catalysis has the catalyst in the same phase as the reactants (all gases, or all in solution). Pt and Fe are solids in gas-phase reactions: heterogeneous.</p>`);
nat(4, `crystal structures`, `In a NaCl crystal with edge length 564 pm, what is the shortest distance between two Na<sup>+</sup> ions, in pm?`, 398.8, 1, `pm`, `<p>Na<sup>+</sup> ions form a fcc lattice with edge a = 564 pm. Nearest neighbours in fcc are along a face diagonal: a/&radic;2 = 564/1.414 = <b>398.8 pm</b>.</p>`, `The Na&ndash;Cl distance is a/2 = 282 pm, but the question asks for Na&ndash;Na.`, () => 564 / Math.SQRT2);
nat(4, `radius ratio`, `In a rock-salt type lattice the anions touch along the face diagonal and the cations just touch the anions along the edge. Find the limiting radius ratio r<sup>+</sup>/r<sup>&minus;</sup> (two decimals).`, 0.41, 0.005, ``, `<p>Along the edge a = 2r<sup>+</sup> + 2r<sup>&minus;</sup>; along the face diagonal &radic;2 a = 4r<sup>&minus;</sup>. So 2(r<sup>+</sup> + r<sup>&minus;</sup>)&radic;2 = 4r<sup>&minus;</sup>, giving r<sup>+</sup>/r<sup>&minus;</sup> = &radic;2 &minus; 1 = <b>0.41</b>.</p>`, ``, () => Math.SQRT2 - 1);
nat(4, `voids`, `Spheres of radius 100 pm form a close-packed lattice. What is the radius of the largest sphere that fits in an octahedral void, in pm?`, 41.4, 0.2, `pm`, `<p>The octahedral void has r = (&radic;2 &minus; 1) R = 0.414 &times; 100 = <b>41.4 pm</b>.</p>`, ``, () => (Math.SQRT2 - 1) * 100);
nat(4, `unit cells`, `A bcc metal has edge length 400 pm. What is the distance between nearest neighbours, in pm?`, 346.4, 1, `pm`, `<p>In bcc the nearest neighbours lie along the body diagonal, which has length &radic;3 a. The distance between touching atoms is half of it: &radic;3 a/2 = 1.732 &times; 400/2 = <b>346.4 pm</b>.</p>`, `For fcc the nearest distance is a/&radic;2.`, () => Math.sqrt(3) * 400 / 2);
nat(4, `Avogadro number`, `KCl has the rock-salt structure with a = 629 pm and density 1.984 g/cm<sup>3</sup>. Taking M = 74.5 g/mol, find N<sub>A</sub> in units of 10<sup>23</sup> mol<sup>&minus;1</sup>.`, 6.04, 0.03, `&times; 10<sup>23</sup>`, `<p>N<sub>A</sub> = ZM/(&rho;a<sup>3</sup>) with Z = 4: a<sup>3</sup> = (6.29 &times; 10<sup>&minus;8</sup> cm)<sup>3</sup> = 2.489 &times; 10<sup>&minus;22</sup> cm<sup>3</sup>. N<sub>A</sub> = 4 &times; 74.5/(1.984 &times; 2.489 &times; 10<sup>&minus;22</sup>) = <b>6.04 &times; 10<sup>23</sup></b>.</p>`, ``, () => 4 * 74.5 / (1.984 * (6.29e-8) ** 3) / 1e23);
nat(4, `magnetic properties`, `A complex has a spin-only magnetic moment of 3.87 BM. How many unpaired electrons does it have?`, 3, 0, ``, `<p>&mu; = &radic;(n(n + 2)): 3 &times; 5 = 15 and &radic;15 = 3.87. So <b>n = 3</b>.</p>`, ``, () => 3);
nat(4, `Freundlich isotherm`, `A gas on charcoal gives x/m = 0.2 g/g at 1 atm and 0.8 g/g at 8 atm. Find n in x/m = kP<sup>1/n</sup>.`, 1.5, 0.01, ``, `<p>Dividing the two: 0.8/0.2 = 8<sup>1/n</sup>, so 4 = 8<sup>1/n</sup>. Taking logs, 1/n = log 4/log 8 = 2/3, hence n = <b>1.5</b>.</p>`, ``, () => Math.log10(8) / Math.log10(4));
nat(4, `Langmuir isotherm`, `A gas follows the Langmuir isotherm &theta; = KP/(1 + KP) with K = 0.50 atm<sup>&minus;1</sup>. What fraction of the surface is covered at P = 3.0 atm?`, 0.6, 0.01, ``, `<p>KP = 0.50 &times; 3.0 = 1.5. &theta; = 1.5/(1 + 1.5) = <b>0.60</b>.</p>`, ``, () => 1.5 / 2.5);
nat(4, `Langmuir isotherm`, `For a gas with K = 0.25 atm<sup>&minus;1</sup> in the Langmuir isotherm, at what pressure (in atm) is 80 % of the surface covered?`, 16, 0, `atm`, `<p>&theta; = KP/(1 + KP) = 0.80, so KP = 0.80/0.20 = 4. P = 4/0.25 = <b>16 atm</b>.</p>`, ``, () => 4 / 0.25);
asr(4, `defects`, `Frenkel defect does not change the density of a crystal.`, `In a Frenkel defect an ion moves from its lattice site to an interstitial site, so the mass and the volume stay the same.`, 0, `<p>Both are true, and R explains A. A Schottky defect removes ions and lowers the density.</p>`);
asr(4, `colloids`, `The coagulation of a negatively charged sol is most effective with Al<sup>3+</sup> ions.`, `According to the Hardy&ndash;Schulze rule, the coagulating power of the ion increases with its charge.`, 0, `<p>Both true, and R is the reason: the ion with the highest charge opposite to the sol&rsquo;s has the lowest flocculation value.</p>`);
asr(4, `adsorption`, `Chemisorption first increases with temperature and then decreases.`, `Chemisorption needs activation energy, but adsorption is exothermic.`, 0, `<p>At low temperature the activation energy barrier limits the rate; as the temperature rises the rate increases. At still higher temperature the exothermic equilibrium shifts against adsorption. R explains A.</p>`);
asr(5, `electrical properties`, `The conductivity of a metal decreases on heating, while that of a semiconductor increases.`, `In metals, heating scatters the electrons more strongly, whereas in a semiconductor heating excites more electrons across the band gap.`, 0, `<p>Both true, and R explains each half of A.</p>`);
asr(5, `colloids`, `Milk can be coagulated by adding a small amount of acid.`, `Casein is a lyophilic sol stabilised only by its charge.`, 2, `<p>A is true: acid (lactic acid in curdling) neutralises the charge on casein and causes coagulation. R is false: casein is stabilised by both charge and solvation (hydration) of the particles; milk is a lyophilic sol only partly stabilised by charge.</p>`);
asr(5, `magnetic properties`, `Ferrimagnetic substances show a net magnetic moment.`, `In ferrimagnetism the dipoles are aligned in opposite directions but in unequal numbers or magnitudes.`, 0, `<p>Both true. In antiferromagnetic substances, the opposing dipoles cancel exactly and the net moment is zero.</p>`);
stm(4, `crystal structures`, `The coordination number of Cs<sup>+</sup> in CsCl is 8.`, `CsCl has a fcc lattice of Cl<sup>&minus;</sup> with Cs<sup>+</sup> in the octahedral voids.`, 1, `<p>I is correct. II is wrong: CsCl has a simple cubic arrangement of Cl<sup>&minus;</sup> with Cs<sup>+</sup> at the body centre (not a fcc structure).</p>`);
stm(4, `adsorption`, `Physisorption is reversible.`, `Chemisorption is generally irreversible and highly specific.`, 0, `<p>Both are correct.</p>`);
stm(4, `defects`, `A Schottky defect is common in ionic solids with similar-sized ions and high coordination numbers.`, `Frenkel defect lowers the density of the solid.`, 1, `<p>I is correct (NaCl, KCl, CsCl). II is wrong: Frenkel defect does not change the density.</p>`);
stm(4, `colloids`, `A lyophilic sol is stable even in the absence of a charge.`, `A lyophobic sol can be coagulated easily by adding a small amount of electrolyte.`, 0, `<p>Both are correct. The lyophilic sol is stabilised by solvation, and the lyophobic one only by charge.</p>`);
stm(5, `catalysis`, `A promoter increases the activity of a catalyst.`, `A promoter is itself a catalyst for the reaction.`, 1, `<p>I is correct. II is wrong: the promoter has little or no catalytic activity on its own. Molybdenum in the Haber process is an example.</p>`);
stm(5, `electrical properties`, `Silicon doped with boron is a p-type semiconductor.`, `The electrical conductivity of the p-type semiconductor is by movement of electrons in the conduction band.`, 1, `<p>I is correct. II is wrong: in p-type conductors the carriers are positive holes in the valence band, produced by the electron-deficient boron.</p>`);
cntS(4, `mixed statements`, `How many of the following statements are correct?<br>(i) A fcc unit cell has 4 octahedral voids.<br>(ii) The packing efficiency of bcc is 74 %.<br>(iii) Schottky defect lowers the density.<br>(iv) Cottrell precipitators neutralise the charge on smoke particles.`, [`One`, `Two`, `Three`, `Four`], 2, `<p>(i) true; (ii) false, bcc is 68 %; (iii) true; (iv) true. Three are correct.</p>`);
cntS(5, `mixed statements`, `How many of the following statements are correct?<br>(i) The coordination number of the cation in ZnS (zinc blende) is 4.<br>(ii) A gold sol with a larger gold number protects better.<br>(iii) Antiferromagnetic substances have zero net magnetic moment.<br>(iv) Chemisorption increases monotonically with temperature.`, [`One`, `Two`, `Three`, `Four`], 1, `<p>(i) true; (ii) false, a smaller gold number means better protection; (iii) true; (iv) false: it increases and then decreases. Two are correct.</p>`);
// ----- level 5 -----
mk(5, `crystal structures`, `In a crystal, the anions X<sup>&minus;</sup> form a cubic close-packed lattice and the cations M<sup>+</sup> occupy all the octahedral voids and one-quarter of the tetrahedral voids. The formula is`, `M<sub>3</sub>X<sub>2</sub>`, [`MX`, `M<sub>2</sub>X`, `M<sub>3</sub>X`], `<p>Per 4 X<sup>&minus;</sup> there are 4 octahedral and 8 tetrahedral voids. M: 4 + (1/4) &times; 8 = 6. M : X = 6 : 4 = 3 : 2.</p>`, `Fractions of voids, not of atoms.`);
mk(5, `crystal structures`, `A compound of A and B has B atoms forming a ccp lattice. If A atoms occupy two-thirds of the octahedral voids, the formula is`, `A<sub>2</sub>B<sub>3</sub>`, [`A<sub>3</sub>B<sub>2</sub>`, `AB<sub>2</sub>`, `A<sub>2</sub>B`], `<p>4 B atoms per cell give 4 octahedral voids. A = (2/3) &times; 4 = 8/3. A : B = 8/3 : 4 = 2 : 3, so A<sub>2</sub>B<sub>3</sub>.</p>`);
mk(5, `packing`, `A solid has a bcc structure. The radius of the largest sphere that can be put into the tetrahedral hole of the bcc lattice, as a fraction of the atom radius, is closest to`, `0.29`, [`0.41`, `0.15`, `0.73`], `<p>In bcc the tetrahedral void sits at (a/2, a/4, 0). Its distance to the nearest atoms is &radic;5 a/4, and the atom radius is R = &radic;3 a/4. The void radius is r = (&radic;5 &minus; &radic;3)a/4, so r/R = (&radic;5 &minus; &radic;3)/&radic;3 = <b>0.29</b>.</p>`);
mk(5, `unit cells`, `A metal with atomic radius r can crystallise as bcc or as fcc. The ratio a(bcc)/a(fcc) of the two edge lengths is`, `0.82`, [`1.00`, `1.22`, `0.71`], `<p>a(bcc) = 4r/&radic;3 = 2.309 r. a(fcc) = 2&radic;2 r = 2.828 r. Ratio = 2.309/2.828 = <b>0.82</b>. (1.22 is the inverse.)</p>`, `The ratio is for the same r, the touching direction differs.`);
mk(5, `density of a unit cell`, `A metal crystallises in fcc as well as in bcc form, with the same atomic radius in both. The ratio of the densities of the fcc form to the bcc form is`, `1.09`, [`2`, `0.92`, `1.5`], `<p>&rho; &prop; Z/a<sup>3</sup>. For fcc: Z = 4, a = 2&radic;2 r, a<sup>3</sup> = 22.63 r<sup>3</sup>, so 4/22.63 = 0.1768. For bcc: Z = 2, a = 4r/&radic;3, a<sup>3</sup> = 12.32 r<sup>3</sup>, so 2/12.32 = 0.1623. Ratio = 0.1768/0.1623 = <b>1.09</b>. (This equals 74/68 = 1.09, the ratio of the packing efficiencies.)</p>`, `The same atom volume means the ratio of densities equals the ratio of packing fractions.`);
mk(5, `X-ray diffraction`, `In Bragg&rsquo;s law n&lambda; = 2d sin&theta;, X-rays of wavelength 154 pm are reflected at first order from planes of spacing 200 pm. The angle &theta; is closest to`, `22.6&deg;`, [`45.0&deg;`, `30.0&deg;`, `38.5&deg;`], `<p>sin&theta; = n&lambda;/(2d) = 154/400 = 0.385, so &theta; = <b>22.6&deg;</b>. Using 154/200 = 0.77 would wrongly give 50.3&deg;.</p>`, `The 2 in 2d sin &theta; matters.`);
mk(5, `defects`, `Fe<sub>0.95</sub>O is a metal-deficient oxide. The fraction of the iron present as Fe<sup>3+</sup> is closest to`, `10.5 %`, [`5 %`, `95 %`, `2.5 %`], `<p>Let x be the Fe<sup>3+</sup> per formula unit. Charge balance: 2(0.95 &minus; x) + 3x = 2, so 1.9 + x = 2 and x = 0.10. Fraction = 0.10/0.95 = <b>10.5 %</b>.</p>`, `Divide by the total iron, 0.95, not by 1.`);
mk(5, `colloids`, `For the Hardy&ndash;Schulze rule, the flocculation values of NaCl, BaCl<sub>2</sub> and AlCl<sub>3</sub> for a negative As<sub>2</sub>S<sub>3</sub> sol are about 50, 0.7 and 0.09 mmol/L. The coagulating power of the ions increases in the order`, `Na<sup>+</sup> &lt; Ba<sup>2+</sup> &lt; Al<sup>3+</sup>`, [`Na<sup>+</sup> &gt; Ba<sup>2+</sup> &gt; Al<sup>3+</sup>`, `Cl<sup>&minus;</sup> &lt; Ba<sup>2+</sup> &lt; Na<sup>+</sup>`, `Al<sup>3+</sup> &lt; Na<sup>+</sup> &lt; Ba<sup>2+</sup>`], `<p>Coagulating power = 1/flocculation value, so it rises as the value falls: Na<sup>+</sup> (50) lowest, then Ba<sup>2+</sup> (0.7), then Al<sup>3+</sup> (0.09). The cations matter because the sol is negative.</p>`);
mk(5, `adsorption`, `Which one of the following plots is a straight line for a gas obeying the Freundlich isotherm?`, `log(x/m) against log P`, [`x/m against P`, `x/m against log P`, `log(x/m) against P`], `<p>x/m = kP<sup>1/n</sup>, so log(x/m) = log k + (1/n) log P, which is linear in log P.</p>`);
nat(5, `crystal structures`, `Packing fraction of a rock-salt crystal: Na<sup>+</sup> (r = 102 pm) and Cl<sup>&minus;</sup> (r = 181 pm) touch along the cell edge. What percentage of the cell volume is occupied by the ions? (4 formula units per cell.)`, 64.6, 0.4, `%`, `<p>a = 2(102 + 181) = 566 pm, so the cell volume is 566<sup>3</sup> = 1.813 &times; 10<sup>8</sup> pm<sup>3</sup>.</p><p>Ion volume per cell = 4 &times; (4/3)&pi;(102<sup>3</sup> + 181<sup>3</sup>) = 4 &times; 4.18879 &times; 6.991 &times; 10<sup>6</sup> = 1.171 &times; 10<sup>8</sup> pm<sup>3</sup>.</p><p>Fraction = 1.171/1.813 = <b>64.6 %</b>.</p>`, `The Cl<sup>&minus;</sup> ions alone would not touch each other, so the packing is below 74 %.`, () => 4 * (4 / 3) * Math.PI * (102 ** 3 + 181 ** 3) / (2 * (102 + 181)) ** 3 * 100);
nat(5, `crystal structures`, `CsCl-type crystal: Cs<sup>+</sup> (r = 167 pm) and Cl<sup>&minus;</sup> (r = 181 pm) touch along the body diagonal. What percentage of the cell volume is occupied by the ions? (1 formula unit per cell.)`, 68.3, 0.4, `%`, `<p>The body diagonal is &radic;3 a = 2(167 + 181) = 696 pm, so a = 401.8 pm and a<sup>3</sup> = 6.489 &times; 10<sup>7</sup> pm<sup>3</sup>.</p><p>Ion volume = (4/3)&pi;(167<sup>3</sup> + 181<sup>3</sup>) = 4.435 &times; 10<sup>7</sup> pm<sup>3</sup>. Fraction = <b>68.3 %</b>.</p>`, `The ions touch along the body diagonal, not the edge.`, () => (4 / 3) * Math.PI * (167 ** 3 + 181 ** 3) / (2 * (167 + 181) / Math.sqrt(3)) ** 3 * 100);
// ----- match, one per group -----
XM(3, `voids`, `xm1`, `Match the quantity (for a close-packed lattice, per atom) with its value`, [`Tetrahedral voids per atom`, `Octahedral voids per atom`, `Fraction of tetrahedral voids occupied by Zn<sup>2+</sup> in zinc blende`, `Fraction of tetrahedral voids occupied by Na<sup>+</sup> in Na<sub>2</sub>O`], [`2 per atom`, `1 per atom`, `half of them`, `all of them`], [0, 1, 2, 3], [`two small cubes per atom.`, `one void per atom.`, `ZnS needs equal numbers of Zn and S, and there are 2 voids per S.`, `Na<sub>2</sub>O has 2 Na per O, so every tetrahedral void is filled.`]);
XM(4, `crystal structures`, `xm2`, `Match the crystal with the coordination numbers (cation : anion)`, [`NaCl`, `CsCl`, `ZnS (zinc blende)`, `CaF<sub>2</sub>`], [`4 : 4`, `6 : 6`, `8 : 8`, `8 : 4`, `4 : 8`], [1, 2, 0, 3], [`octahedral sites.`, `body-centred cubic arrangement.`, `tetrahedral sites for both.`, `Ca<sup>2+</sup> has 8, F<sup>&minus;</sup> has 4.`]);
XM(3, `radius ratio`, `xm3`, `Match the radius ratio r<sup>+</sup>/r<sup>&minus;</sup> with the coordination number`, [`0.155&ndash;0.225`, `0.225&ndash;0.414`, `0.414&ndash;0.732`, `0.732&ndash;1.0`], [`3`, `4`, `6`, `8`], [0, 1, 2, 3], [`triangular hole.`, `tetrahedral hole.`, `octahedral hole.`, `cubic hole.`]);
XM(4, `defects`, `xm4`, `Match the defect with its effect`, [`Schottky defect`, `Frenkel defect`, `F-centre`, `Doping NaCl with SrCl<sub>2</sub>`], [`no change in density`, `density decreases`, `gives colour to the crystal`, `creates cation vacancies`], [1, 0, 2, 3], [`ions are lost from the crystal.`, `the ion only moves.`, `trapped electrons absorb light.`, `Sr<sup>2+</sup> replaces Na<sup>+</sup> and leaves a vacancy for charge balance.`]);
XM(4, `magnetic properties`, `xm5`, `Match the type of magnetism with the arrangement of magnetic dipoles`, [`Paramagnetism`, `Ferromagnetism`, `Antiferromagnetism`, `Ferrimagnetism`], [`random until a field is applied`, `all dipoles aligned in the same direction (domains)`, `equal dipoles in opposite directions, zero net moment`, `opposite dipoles in unequal number or size, net moment remains`], [0, 1, 2, 3], [`unpaired electrons, aligned only by an external field.`, `e.g. Fe, Co, Ni, CrO<sub>2</sub>.`, `e.g. MnO.`, `e.g. Fe<sub>3</sub>O<sub>4</sub>, ferrites.`]);
XM(3, `colloids`, `xm6`, `Match the technique or property with what it shows`, [`Dialysis`, `Electrophoresis`, `Tyndall effect`, `Brownian motion`], [`removal of dissolved ions through a membrane`, `migration of charged colloid particles in an electric field`, `scattering of light by colloidal particles`, `zig-zag motion due to collisions with the medium`], [0, 1, 2, 3], [`purifies a sol.`, `shows the charge on the particles.`, `the beam of light is visible.`, `keeps particles from settling.`]);
XM(4, `adsorption`, `xm7`, `Match the term with its description`, [`Freundlich isotherm`, `Langmuir isotherm`, `Krafft temperature`, `Critical micelle concentration`], [`log(x/m) against log P is a straight line`, `coverage reaches a limit at high pressure (monolayer)`, `temperature above which micelles can form`, `concentration above which micelles form`], [0, 1, 2, 3], [`power-law equation.`, `&theta; = KP/(1 + KP) tends to 1.`, `solubility of the surfactant rises sharply.`, `below it the surfactant is mainly single molecules.`]);
XM(3, `catalysis`, `xm8`, `Match the catalytic term with an example`, [`Promoter`, `Catalytic poison`, `Autocatalyst`, `Biocatalyst`], [`Mo in the Haber process`, `As in the contact process (Pt catalyst)`, `Mn<sup>2+</sup> in KMnO<sub>4</sub> with oxalic acid`, `urease`], [0, 1, 2, 3], [`enhances the activity of Fe.`, `deactivates the Pt surface.`, `formed in the reaction, it speeds the reaction up.`, `an enzyme catalysing the hydrolysis of urea.`]);
// ----- passages -----
P(4, `voids`, `xp5`, `The formula of the mixed oxide is`, `AB<sub>2</sub>O<sub>4</sub>`, [`ABO<sub>4</sub>`, `A<sub>2</sub>BO<sub>4</sub>`, `AB<sub>2</sub>O<sub>2</sub>`], `<p>Per 4 oxide ions there are 8 tetrahedral and 4 octahedral voids. A: 8/8 = 1. B: 4/2 = 2. Formula AB<sub>2</sub>O<sub>4</sub>.</p>`);
PN(4, `voids`, `xp5`, `How many cations of B per 4 oxide ions?`, 2, 0, ``, `<p>Octahedral voids: 4; B fills one-half of them: <b>2</b>.</p>`, ``, () => 4 / 2);
PN(5, `voids`, `xp5`, `If A has oxidation state +2, what is the oxidation state of B?`, 3, 0, ``, `<p>Charge balance for AB<sub>2</sub>O<sub>4</sub>: 2 + 2x = 8, so x = <b>+3</b>.</p>`, ``, () => (8 - 2) / 2);
PN(4, `Freundlich isotherm`, `xp6`, `Find the value of n.`, 1.5, 0.01, ``, `<p>0.8/0.2 = 8<sup>1/n</sup>, so 4 = 8<sup>1/n</sup>, 1/n = 2/3 and n = <b>1.5</b>.</p>`, ``, () => Math.log10(8) / Math.log10(4));
PN(5, `Freundlich isotherm`, `xp6`, `What amount (g per g) is adsorbed at 27 atm?`, 1.8, 0.02, `g/g`, `<p>1/n = 2/3, k = 0.2 (at 1 atm). x/m = 0.2 &times; 27<sup>2/3</sup> = 0.2 &times; 9 = <b>1.8 g/g</b>.</p>`, ``, () => 0.2 * 27 ** (2 / 3));
P(4, `Freundlich isotherm`, `xp6`, `The slope of a plot of log(x/m) against log P is`, `0.667`, [`1.5`, `0.2`, `0.8`], `<p>The slope is 1/n = 2/3 = 0.667. Using n = 1.5 as the slope is the usual error.</p>`);
// ----- number templates -----
gens.push(
  { id: 'sd-g24', type: 'nat', level: 4, exams: EX[4], sub: `Bragg's law`,
    make(rng) {
      const lam = choose(rng, [154, 150, 140, 71]); const th = choose(rng, [15, 20, 25, 30, 40]); const n = choose(rng, [1, 2]); const d = n * lam / (2 * Math.sin(th * Math.PI / 180));
      return { q: `X-rays of wavelength ${lam} pm give an order n = ${n} reflection at &theta; = ${th}&deg;. Find the spacing d between the lattice planes in pm.`, answer: +d.toFixed(1), tol: Math.max(0.5, d * 0.005), unit: `pm`, lam, th, n,
        sol: `<p>n&lambda; = 2d sin&theta;, so d = n&lambda;/(2 sin&theta;) = ${n} &times; ${lam}/(2 &times; sin ${th}&deg;) = ${n * lam}/${(2 * Math.sin(th * Math.PI / 180)).toFixed(4)} = <b>${d.toFixed(1)} pm</b>.</p>`, trap: `Do not drop the factor 2.` };
    }, verify: (p) => p.n * p.lam / (2 * Math.sin(p.th / 180 * Math.PI)) },
  { id: 'sd-g25', type: 'nat', level: 3, exams: EX[3], sub: `radius of a void`,
    make(rng) {
      const R = pick(rng, 80, 200, 10); const [nm, f] = choose(rng, [[`tetrahedral`, 0.225], [`octahedral`, 0.414], [`trigonal (triangular)`, 0.155]]); const ans = R * f;
      return { q: `Spheres of radius ${R} pm are close packed. What is the radius of the largest sphere that fits in a ${nm} void, in pm? (Use the standard ratios 0.155, 0.225, 0.414.)`, answer: +ans.toFixed(1), tol: Math.max(0.3, ans * 0.01), unit: `pm`, R, nm,
        sol: `<p>The ratio r/R for a ${nm} void is ${f}. So r = ${f} &times; ${R} = <b>${ans.toFixed(1)} pm</b>.</p>` };
    }, verify: (p) => p.R * ({ tetrahedral: Math.sqrt(1.5) - 1, octahedral: Math.SQRT2 - 1, 'trigonal (triangular)': 2 / Math.sqrt(3) - 1 })[p.nm] },
  { id: 'sd-g26', type: 'mcq', level: 3, exams: EXM[3], sub: `coordination numbers`,
    make(rng) {
      const pool = [[`NaCl`, `6 : 6`], [`CsCl`, `8 : 8`], [`ZnS (zinc blende)`, `4 : 4`], [`CaF<sub>2</sub> (Ca : F)`, `8 : 4`], [`Na<sub>2</sub>O (Na : O)`, `4 : 8`]];
      const [nm, cn] = choose(rng, pool); const { options, answer } = shuffleOpts(rng, cn, pool.filter((x) => x[1] !== cn).map((x) => x[1]).slice(0, 3));
      return { q: `The coordination numbers (cation : anion) in ${nm} are`, options, answer, cn, sol: `<p>${nm}: <b>${cn}</b>.</p>` };
    }, verify: (p) => p.options.indexOf(p.cn) },
  { id: 'sd-g27', type: 'nat', level: 4, exams: EX[4], sub: `number of formula units from density`,
    make(rng) {
      const s = choose(rng, SALT); const rho = +(s.Z * s.M / (NA * (s.a * 1e-10) ** 3)).toPrecision(3); const z = rho * (s.a * 1e-10) ** 3 * NA / s.M;
      return { q: `${s.n} has molar mass ${s.M} g/mol, density ${rho} g/cm<sup>3</sup> and a cubic unit cell of edge ${s.a} pm. How many formula units are in the unit cell (nearest whole number)? (N<sub>A</sub> = 6.022 &times; 10<sup>23</sup>)`, answer: s.Z, tol: 0, s_Z: s.Z, rho, a: s.a, M: s.M,
        sol: `<p>Z = &rho; a<sup>3</sup> N<sub>A</sub>/M = ${rho} &times; (${s.a} &times; 10<sup>&minus;10</sup>)<sup>3</sup> &times; 6.022 &times; 10<sup>23</sup>/${s.M} = ${z.toFixed(2)}, which rounds to <b>${s.Z}</b>.</p>`, trap: `Convert pm to cm: 1 pm = 10<sup>&minus;10</sup> cm.` };
    }, verify: (p) => Math.round(p.rho * (p.a * 1e-10) ** 3 * 6.022e23 / p.M) },
  { id: 'sd-g28', type: 'nat', level: 3, exams: EX[3], sub: `spin-only magnetic moment`,
    make(rng) {
      const [ion, d] = choose(rng, [[`Ti<sup>3+</sup>`, 1], [`V<sup>3+</sup>`, 2], [`Cr<sup>3+</sup>`, 3], [`Mn<sup>2+</sup>`, 5], [`Fe<sup>3+</sup>`, 5], [`Fe<sup>2+</sup>`, 6], [`Co<sup>2+</sup>`, 7], [`Ni<sup>2+</sup>`, 8], [`Cu<sup>2+</sup>`, 9]]);
      const n = d <= 5 ? d : 10 - d; const mu = Math.sqrt(n * (n + 2));
      return { q: `Find the spin-only magnetic moment of ${ion} (d<sup>${d}</sup>, weak field, high spin) in BM.`, answer: +mu.toFixed(2), tol: 0.02, unit: `BM`, d,
        sol: `<p>d<sup>${d}</sup> has ${n} unpaired electron${n > 1 ? 's' : ''} (Hund&rsquo;s rule). &mu; = &radic;(n(n + 2)) = &radic;(${n} &times; ${n + 2}) = <b>${mu.toFixed(2)} BM</b>.</p>`, trap: `For d<sup>6</sup> to d<sup>9</sup> count the unpaired electrons as 10 &minus; d.` };
    }, verify: (p) => { const n = [0, 1, 2, 3, 4, 5, 4, 3, 2, 1, 0][p.d]; return Math.sqrt(n * (n + 2)); } },
  { id: 'sd-g29', type: 'mcq', level: 4, exams: EXM[4], sub: `Hardy-Schulze rule`,
    make(rng) {
      const sols = [[`As<sub>2</sub>S<sub>3</sub>`, `negative`], [`gold`, `negative`], [`Fe(OH)<sub>3</sub>`, `positive`], [`Al(OH)<sub>3</sub>`, `positive`]];
      const salts = [[`NaCl`, 1, 1], [`BaCl<sub>2</sub>`, 2, 1], [`AlCl<sub>3</sub>`, 3, 1], [`Na<sub>2</sub>SO<sub>4</sub>`, 1, 2], [`Na<sub>3</sub>PO<sub>4</sub>`, 1, 3], [`K<sub>4</sub>[Fe(CN)<sub>6</sub>]`, 1, 4]];
      const [sn, sg] = choose(rng, sols); const eff = (s) => (sg === 'negative' ? s[1] : s[2]);
      for (let t = 0; t < 40; t++) { const idx = [0, 1, 2, 3, 4, 5]; for (let i = 5; i > 0; i--) { const j = int(rng, 0, i); [idx[i], idx[j]] = [idx[j], idx[i]]; } const four = idx.slice(0, 4).map((i) => salts[i]); const mx = Math.max(...four.map(eff)); if (four.filter((s) => eff(s) === mx).length === 1) {
        const right = four.find((s) => eff(s) === mx); const { options, answer } = shuffleOpts(rng, right[0], four.filter((s) => s !== right).map((s) => s[0]));
        return { q: `Which electrolyte is the most effective in coagulating the ${sg} ${sn} sol?`, options, answer, right: right[0], sg, four: four.map((s) => s[0]),
          sol: `<p>The coagulating ion is the one with the charge <i>opposite</i> to the sol (${sg === 'negative' ? 'cations' : 'anions'} here). Its power grows with its charge (Hardy&ndash;Schulze rule). The highest is for <b>${right[0]}</b>.</p>`, trap: `Look at the ion with the opposite charge to the sol.` }; } }
      return { q: `Which electrolyte is the most effective in coagulating a negative As<sub>2</sub>S<sub>3</sub> sol?`, options: [`NaCl`, `AlCl<sub>3</sub>`, `Na<sub>3</sub>PO<sub>4</sub>`, `Na<sub>2</sub>SO<sub>4</sub>`], answer: 1, right: `AlCl<sub>3</sub>`, sg: `negative`, four: [`NaCl`, `AlCl<sub>3</sub>`, `Na<sub>3</sub>PO<sub>4</sub>`, `Na<sub>2</sub>SO<sub>4</sub>`], sol: `<p>Al<sup>3+</sup> has the highest charge among the cations: <b>AlCl<sub>3</sub></b>.</p>` };
    }, verify: (p) => { const ch = { 'NaCl': [1, 1], 'BaCl<sub>2</sub>': [2, 1], 'AlCl<sub>3</sub>': [3, 1], 'Na<sub>2</sub>SO<sub>4</sub>': [1, 2], 'Na<sub>3</sub>PO<sub>4</sub>': [1, 3], 'K<sub>4</sub>[Fe(CN)<sub>6</sub>]': [1, 4] }; const k = p.sg === 'negative' ? 0 : 1; let best = p.four[0]; for (const s of p.four) if (ch[s][k] > ch[best][k]) best = s; return p.options.indexOf(best); } },
  { id: 'sd-g30', type: 'nat', level: 3, exams: EX[3], sub: `flocculation values`,
    make(rng) {
      const a = choose(rng, [40, 50, 60]); const b = choose(rng, [0.4, 0.5, 0.8, 1]); const ans = a / b;
      return { q: `The flocculation values of a negative sol are ${a} mmol/L for NaCl and ${b} mmol/L for BaCl<sub>2</sub>. How many times more effective is BaCl<sub>2</sub> than NaCl?`, answer: +ans.toFixed(1), tol: Math.max(0.1, ans * 0.01), a, b,
        sol: `<p>Coagulating power &prop; 1/flocculation value. Ratio = ${a}/${b} = <b>${+ans.toFixed(1)}</b>.</p>`, trap: `The smaller flocculation value belongs to the more effective ion.` };
    }, verify: (p) => (1 / p.b) / (1 / p.a) },
  { id: 'sd-g31', type: 'nat', level: 5, exams: EX[5], sub: `packing fraction of an ionic crystal`,
    make(rng) {
      const [nm, rp, rm, kind] = choose(rng, [[`NaCl`, 102, 181, `rs`], [`KCl`, 138, 181, `rs`], [`CsCl`, 167, 181, `cs`], [`ZnS (zinc blende)`, 74, 184, `zb`]]);
      const a = kind === `rs` ? 2 * (rp + rm) : kind === `cs` ? 2 * (rp + rm) / Math.sqrt(3) : 4 * (rp + rm) / Math.sqrt(3); const Z = kind === `cs` ? 1 : 4; const f = Z * (4 / 3) * Math.PI * (rp ** 3 + rm ** 3) / a ** 3 * 100;
      return { q: `In ${nm}, the cation (r = ${rp} pm) and anion (r = ${rm} pm) touch each other ${kind === `rs` ? 'along the edge' : kind === `cs` ? 'along the body diagonal' : 'along the body diagonal (cation in a tetrahedral void)'}. What percentage of the unit cell volume do the ions occupy? (${Z} formula unit${Z > 1 ? 's' : ''} per cell.)`, answer: +f.toFixed(1), tol: 0.4, unit: `%`, rp, rm, kind,
        sol: `<p>Edge: a = ${kind === `rs` ? '2(r<sup>+</sup> + r<sup>&minus;</sup>)' : kind === `cs` ? '2(r<sup>+</sup> + r<sup>&minus;</sup>)/&radic;3' : '4(r<sup>+</sup> + r<sup>&minus;</sup>)/&radic;3'} = ${a.toFixed(1)} pm.</p><p>Ion volume per cell = ${Z} &times; (4/3)&pi;(${rp}<sup>3</sup> + ${rm}<sup>3</sup>). Fraction = <b>${f.toFixed(1)} %</b>.</p>`, trap: `Use both ions in the volume, and check which direction the ions touch.` };
    }, verify: (p) => { const k = { rs: 2, cs: 2 / Math.sqrt(3), zb: 4 / Math.sqrt(3) }[p.kind]; const Z = p.kind === 'cs' ? 1 : 4; return 100 * Z * (4 / 3) * Math.PI * (p.rp ** 3 + p.rm ** 3) / (k * (p.rp + p.rm)) ** 3; } },
  { id: 'sd-g32', type: 'mcq', level: 3, exams: EXM[3], sub: `effect of defects`,
    make(rng) {
      const pool = [[`Schottky defect`, `lowers the density`], [`Frenkel defect`, `leaves the density unchanged`], [`an F-centre`, `colours the crystal`], [`a metal-deficiency defect`, `makes the compound non-stoichiometric with a variable oxidation state of the metal`], [`doping with an aliovalent cation`, `creates vacancies or free carriers`]];
      const [nm, e] = choose(rng, pool); const { options, answer } = shuffleOpts(rng, e, pool.filter((x) => x[1] !== e).map((x) => x[1]).slice(0, 3));
      return { q: `Which effect is correct for ${nm}?`, options, answer, e, sol: `<p>${nm[0].toUpperCase() + nm.slice(1)} ${e}.</p>` };
    }, verify: (p) => p.options.indexOf(p.e) },
);

export default {
  topic: 'solid-state-surface',
  groups,
  items: L.map((it, i) => ({ id: `sd-${String(i + 1).padStart(3, '0')}`, ...it })),
  gens,
};
